function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPndReceipts(
  query: Record<string, string | number | boolean>,
): Promise<PndReceiptListItem[]> {
  const res = await apiClient.get<BffResponse<PndReceiptListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPndReceipt(sttRec: string): Promise<PndReceipt> {
  const res = await apiClient.get<BffResponse<PndReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPndReceipt(body: PndReceiptWrite): Promise<PndReceipt> {
  const res = await apiClient.post<BffResponse<PndReceipt>>(BASE, body);
  return unwrap(res);
}

export async function updatePndReceipt(sttRec: string, body: PndReceiptWrite): Promise<PndReceipt> {
  const res = await apiClient.put<BffResponse<PndReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
