import React, { useEffect, useMemo, useState } from 'react';
import {
  Button,
  Checkbox,
  Input,
  LeaveConfirmModal,
  Select,
  dispatchAppToast,
  useDirtyTracking,
  useFormLeaveGuard,
} from '@linm-soft-org/linm-web-common-components';
import { useParams, useSearchParams } from 'react-router-dom';
import { DocumentFormHeader } from '../../../components/layout/DocumentFormHeader';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { ktService } from '../../../services/kt/ktService';
import {
  createPndReceipt,
  getPndReceipt,
  updatePndReceipt,
  type PndReceipt,
  type PndReceiptWrite,
  type PndReceiptWriteLine,
} from '../../../services/kt/pndReceipts';
import df from '../../../styles/documentForm.module.css';

const LEAVE_MESSAGE = 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.';

interface LineState {
  sttRec0: string;
  maVt: string;
  tenVt: string;
  dvt: string;
  maVitri: string;
  maKhoI: string;
  ton13: string;
  soLuong: string;
  giaNt: string;
  tienNt: string;
  tkVt: string;
  maNxI: string;
  maVvI: string;
  maHdI: string;
  maPhiI: string;
  maTtlnI: string;
  maTtcpI: string;
  maBpI: string;
}

interface FormState {
  maGd: string;
  maPost: string;
  pnGiaTb: boolean;
  maQuyen: string;
  ngayCt: string;
  ngayLct: string;
  soCt: string;
  soLo: string;
  ngayLo: string;
  maKh: string;
  tenKh: string;
  ongBa: string;
  diaChi: string;
  dienGiai: string;
  maNt: string;
  tyGia: string;
  lenhSo: string;
  lenhPo: string;
  lenhRo: string;
  tSoLuong1: string;
}

function today(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function emptyLine(): LineState {
  return {
    sttRec0: '',
    maVt: '',
    tenVt: '',
    dvt: '',
    maVitri: '',
    maKhoI: '',
    ton13: '0',
    soLuong: '0',
    giaNt: '0',
    tienNt: '',
    tkVt: '',
    maNxI: '',
    maVvI: '',
    maHdI: '',
    maPhiI: '',
    maTtlnI: '',
    maTtcpI: '',
    maBpI: '',
  };
}

function emptyForm(): FormState {
  return {
    maGd: '4',
    maPost: '3',
    pnGiaTb: false,
    maQuyen: '',
    ngayCt: today(),
    ngayLct: today(),
    soCt: '',
    soLo: '',
    ngayLo: '',
    maKh: '',
    tenKh: '',
    ongBa: '',
    diaChi: '',
    dienGiai: '',
    maNt: 'VND',
    tyGia: '',
    lenhSo: '',
    lenhPo: '',
    lenhRo: '',
    tSoLuong1: '0',
  };
}

function round4(value: number): number {
  if (!Number.isFinite(value)) return 0;
  const sign = value < 0 ? -1 : 1;
  return (sign * Math.round(Math.abs(value) * 10000)) / 10000;
}

function showMoney(value: number): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value);
}

function parseAmount(raw: string): number | null {
  const text = raw.trim();
  if (!text) return null;
  const value = Number(text.replace(',', '.'));
  return Number.isFinite(value) ? value : null;
}

function amountOrZero(raw: string): number {
  return parseAmount(raw) ?? 0;
}

function textOrNull(value: string): string | null {
  const text = value.trim();
  return text ? text : null;
}

function dateOrNull(value: string): string | null {
  return value.trim() ? value : null;
}

function fillTienNt(line: LineState): LineState {
  if (line.tienNt.trim() !== '') return line;
  if (line.soLuong.trim() === '' || line.giaNt.trim() === '') return line;
  const soLuong = parseAmount(line.soLuong);
  const giaNt = parseAmount(line.giaNt);
  if (soLuong == null || giaNt == null) return line;
  return { ...line, tienNt: String(round4(soLuong * giaNt)) };
}

function previewGia(giaNt: string, tyGia: string): number {
  if (!giaNt.trim() || !tyGia.trim()) return 0;
  const rate = parseAmount(tyGia);
  if (rate == null || rate === 0) return 0;
  return round4(amountOrZero(giaNt) * rate);
}

function previewTien(tienNt: string, tyGia: string): number {
  if (!tienNt.trim() || !tyGia.trim()) return 0;
  const rate = parseAmount(tyGia);
  if (rate == null || rate === 0) return 0;
  return round4(amountOrZero(tienNt) * rate);
}

function fromReceipt(receipt: PndReceipt, copy: boolean): { form: FormState; lines: LineState[] } {
  return {
    form: {
      maGd: receipt.maGd === '9' ? '9' : '4',
      maPost: receipt.maPost === '9' ? '9' : '3',
      pnGiaTb: receipt.pnGiaTb === 1,
      maQuyen: receipt.maQuyen ?? '',
      ngayCt: receipt.ngayCt ?? '',
      ngayLct: receipt.ngayLct ?? '',
      soCt: receipt.soCt ?? '',
      soLo: receipt.soLo ?? '',
      ngayLo: receipt.ngayLo ?? '',
      maKh: receipt.maKh ?? '',
      tenKh: receipt.tenKh ?? '',
      ongBa: receipt.ongBa ?? '',
      diaChi: receipt.diaChi ?? '',
      dienGiai: receipt.dienGiai ?? '',
      maNt: receipt.maNt ?? '',
      tyGia: receipt.tyGia == null ? '' : String(receipt.tyGia),
      lenhSo: receipt.lenhSo ?? '',
      lenhPo: receipt.lenhPo ?? '',
      lenhRo: receipt.lenhRo ?? '',
      tSoLuong1: copy ? '0' : String(receipt.tSoLuong1 ?? 0),
    },
    lines: (receipt.lines ?? []).map(line => ({
      sttRec0: copy ? '' : line.sttRec0 ?? '',
      maVt: line.maVt ?? '',
      tenVt: line.tenVt ?? '',
      dvt: line.dvt ?? '',
      maVitri: line.maVitri ?? '',
      maKhoI: line.maKhoI ?? '',
      ton13: String(line.ton13 ?? 0),
      soLuong: String(line.soLuong ?? 0),
      giaNt: String(line.giaNt ?? 0),
      tienNt: line.tienNt == null ? '' : String(line.tienNt),
      tkVt: line.tkVt ?? '',
      maNxI: line.maNxI ?? '',
      maVvI: line.maVvI ?? '',
      maHdI: line.maHdI ?? '',
      maPhiI: line.maPhiI ?? '',
      maTtlnI: line.maTtlnI ?? '',
      maTtcpI: line.maTtcpI ?? '',
      maBpI: line.maBpI ?? '',
    })),
  };
}

const lineColumns: Array<{ key: keyof LineState; header: string; disabled?: boolean; maxLength?: number; decimal?: boolean }> = [
  { key: 'maVt', header: 'Hàng hoá', maxLength: 30 },
  { key: 'tenVt', header: 'Tên hàng hoá', disabled: true },
  { key: 'dvt', header: 'ĐVT', disabled: true },
  { key: 'maVitri', header: 'Vị trí', maxLength: 30 },
  { key: 'maKhoI', header: 'Kho', maxLength: 30 },
  { key: 'ton13', header: 'Tồn', disabled: true, decimal: true },
  { key: 'soLuong', header: 'Số lượng', decimal: true },
  { key: 'giaNt', header: 'Giá', decimal: true },
  { key: 'tienNt', header: 'Nguyên tệ', decimal: true },
  { key: 'tkVt', header: 'Tk Nợ', maxLength: 30 },
  { key: 'maNxI', header: 'Tk có', maxLength: 30 },
  { key: 'maVvI', header: 'V.Việc', maxLength: 30 },
  { key: 'maHdI', header: 'Hợp đồng', maxLength: 30 },
  { key: 'maPhiI', header: 'khoản mục', maxLength: 30 },
  { key: 'maTtlnI', header: 'Trung tâm lợi nhuận', maxLength: 30 },
  { key: 'maTtcpI', header: 'Trung tâm chi phí', maxLength: 30 },
  { key: 'maBpI', header: 'Phòng ban', maxLength: 30 },
];

const PndFormPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const dispatch = useAppDispatch();
  const { sttRec } = useParams();
  const [searchParams] = useSearchParams();
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = searchParams.get('mode') === 'view';
  const isNew = !sttRec;
  const isCopy = isNew && copyFrom.length > 0;
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({ message: LEAVE_MESSAGE });
  const { markDirty, markClean } = useDirtyTracking(isView ? undefined : onDirtyChange);
  const [form, setForm] = useState<FormState>(emptyForm);
  const [lines, setLines] = useState<LineState[]>([]);
  const [selectedLine, setSelectedLine] = useState(-1);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [loaded, setLoaded] = useState(isNew && !isCopy);

  useEffect(() => {
    if (isNew && !isCopy) {
      setForm(emptyForm());
      setLines([]);
      setSelectedLine(-1);
      setError('');
      setLoaded(true);
      markClean();
      return;
    }
    const key = isCopy ? copyFrom : sttRec;
    if (!key) return;
    let cancelled = false;
    setLoading(true);
    setError('');
    void getPndReceipt(key)
      .then(receipt => {
        if (cancelled) return;
        if (!receipt?.sttRec) {
          setError('Không tìm thấy phiếu nhập kho');
          setLoaded(false);
          return;
        }
        const mapped = fromReceipt(receipt, isCopy);
        setForm(mapped.form);
        setLines(mapped.lines);
        setSelectedLine(mapped.lines.length > 0 ? 0 : -1);
        setLoaded(true);
        markClean();
      })
      .catch(err => {
        if (cancelled) return;
        setLoaded(false);
        setError(getApiErrorMessage(err, 'Không tìm thấy phiếu nhập kho'));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [sttRec, copyFrom, isCopy, isNew, markClean]);

  const totals = useMemo(() => {
    const tSoLuong = round4(lines.reduce((sum, line) => sum + amountOrZero(line.soLuong), 0));
    const tTienNt = round4(lines.reduce((sum, line) => sum + (line.tienNt.trim() ? amountOrZero(line.tienNt) : 0), 0));
    const tTien = round4(lines.reduce((sum, line) => sum + previewTien(line.tienNt, form.tyGia), 0));
    return { tSoLuong, tTienNt, tTien };
  }, [lines, form.tyGia]);

  const patchForm = (patch: Partial<FormState>) => {
    setForm(prev => ({ ...prev, ...patch }));
    if (!isView) markDirty();
  };

  const patchLine = (index: number, patch: Partial<LineState>) => {
    setLines(prev => prev.map((line, i) => (i === index ? fillTienNt({ ...line, ...patch }) : line)));
    if (!isView) markDirty();
  };

  const onBlurCustomer = async () => {
    const code = form.maKh.trim();
    if (!code) {
      setForm(prev => ({ ...prev, tenKh: '' }));
      return;
    }
    try {
      const res = await ktService.searchCustomers({ search: code, page: 1, pageSize: 20, isActive: true });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setForm(prev => ({ ...prev, tenKh: hit?.name ?? '' }));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const onBlurMaterial = async (index: number) => {
    const code = lines[index]?.maVt.trim() ?? '';
    if (!code) {
      setLines(prev => prev.map((line, i) => (i === index ? { ...line, tenVt: '', dvt: '' } : line)));
      return;
    }
    try {
      const res = await ktService.searchMaterials({ search: code, page: 1, pageSize: 20 });
      const hit = res.items.find(item => item.code.trim().toLowerCase() === code.toLowerCase());
      setLines(prev => prev.map((line, i) => (
        i === index ? { ...line, tenVt: hit?.name ?? '', dvt: hit?.unitCode ?? '' } : line
      )));
    } catch {
      /* tra cứu không chặn gõ */
    }
  };

  const renderLineInput = (line: LineState, index: number, col: typeof lineColumns[number]) => (
    <td key={col.key}>
      <Input
        disabled={readOnly || col.disabled}
        maxLength={col.maxLength}
        inputMode={col.decimal ? 'decimal' : undefined}
        data-testid={`ct-pnd-line-${index}-${col.key}`}
        value={line[col.key]}
        onChange={event => patchLine(index, { [col.key]: event.target.value })}
        onBlur={col.key === 'maVt' ? () => { void onBlurMaterial(index); } : undefined}
      />
    </td>
  );

  const validate = (): string => {
    if (!form.maKh.trim()) return 'Bạn chưa nhập mã đối tượng';
    for (const line of lines) {
      if (!line.maKhoI.trim()) return 'Bạn chưa nhập kho nhập ';
      if (!line.tkVt.trim()) return 'Bạn chưa nhập tài khoản nợ';
      if (!line.maNxI.trim()) return 'Bạn chưa nhập tài có ';
    }
    return '';
  };

  const buildBody = (): PndReceiptWrite => ({
    maCt: 'PND',
    maGd: form.maGd,
    maPost: form.maPost,
    pnGiaTb: form.pnGiaTb ? 1 : 0,
    maQuyen: textOrNull(form.maQuyen),
    ngayCt: dateOrNull(form.ngayCt),
    ngayLct: dateOrNull(form.ngayLct),
    soCt: textOrNull(form.soCt),
    soLo: textOrNull(form.soLo),
    ngayLo: dateOrNull(form.ngayLo),
    maKh: textOrNull(form.maKh),
    ongBa: textOrNull(form.ongBa),
    diaChi: textOrNull(form.diaChi),
    dienGiai: textOrNull(form.dienGiai),
    maNt: textOrNull(form.maNt),
    tyGia: parseAmount(form.tyGia),
    lenhSo: textOrNull(form.lenhSo),
    lenhPo: textOrNull(form.lenhPo),
    lenhRo: textOrNull(form.lenhRo),
    lines: lines.map(line => {
      const row: PndReceiptWriteLine = {
        maVt: textOrNull(line.maVt),
        maVitri: textOrNull(line.maVitri),
        maKhoI: textOrNull(line.maKhoI),
        ton13: amountOrZero(line.ton13),
        soLuong: parseAmount(line.soLuong),
        giaNt: parseAmount(line.giaNt),
        tienNt: parseAmount(line.tienNt),
        tkVt: textOrNull(line.tkVt),
        maNxI: textOrNull(line.maNxI),
        maVvI: textOrNull(line.maVvI),
        maHdI: textOrNull(line.maHdI),
        maPhiI: textOrNull(line.maPhiI),
        maTtlnI: textOrNull(line.maTtlnI),
        maTtcpI: textOrNull(line.maTtcpI),
        maBpI: textOrNull(line.maBpI),
      };
      if (!isNew && line.sttRec0.trim()) row.sttRec0 = line.sttRec0.trim();
      return row;
    }),
  });

  const onSave = async () => {
    const message = validate();
    if (message) {
      setError(message);
      return;
    }
    setSaving(true);
    setError('');
    try {
      const body = buildBody();
      const saved = isNew || !sttRec
        ? await createPndReceipt(body)
        : await updatePndReceipt(sttRec, body);
      markClean();
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu phiếu nhập kho' });
      navigate(`/kt/pnd/${saved.sttRec}`);
    } catch (err) {
      const messageText = getApiErrorMessage(err, 'Lưu thất bại');
      setError(messageText);
      dispatchAppToast(dispatch, { type: 'error', message: messageText });
    } finally {
      setSaving(false);
    }
  };

  const title = isView ? 'Xem phiếu nhập kho' : isNew ? 'Thêm phiếu nhập kho' : 'Sửa phiếu nhập kho';
  const readOnly = isView;

  return (
    <div className={df.page} data-testid="ct-pnd-form">
      <DocumentFormHeader
        title={title}
        isNew={isNew}
        isReadOnly={readOnly}
        saving={saving}
        testIdPrefix="ct-pnd"
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        onBack={() => guardedNavigate(() => navigate('/kt/pnd'))}
        onSave={loaded && !readOnly ? () => { void onSave(); } : undefined}
      />
      <LeaveConfirmModal {...leaveConfirmModalProps} />
      {error && <div className={df.errorBanner}>{error}</div>}
      {loading && <div className={df.loading}>Đang tải...</div>}
      {loaded && (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <Select label="Loại giao dịch" data-testid="ct-pnd-field-maGd" disabled={readOnly} value={form.maGd} options={[{ value: '4', label: 'Nhập sản xuất' }, { value: '9', label: 'Nhập khác' }]} onChange={event => patchForm({ maGd: event.target.value })} />
              <Select label="Trạng thái" data-testid="ct-pnd-field-maPost" disabled={readOnly} value={form.maPost} options={[{ value: '3', label: 'Lập chứng từ' }, { value: '9', label: 'Hạch toán sổ cái' }]} onChange={event => patchForm({ maPost: event.target.value })} />
              <Checkbox label="Giá trung bình" data-testid="ct-pnd-field-pnGiaTb" disabled={readOnly} checked={form.pnGiaTb} onChange={event => patchForm({ pnGiaTb: event.target.checked })} />
              <div>
                <label className={df.label}>Quyền số</label>
                <Input maxLength={30} disabled={readOnly} data-testid="ct-pnd-field-maQuyen" value={form.maQuyen} onChange={event => patchForm({ maQuyen: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Ngày C.từ</label>
                <Input type="date" disabled={readOnly} data-testid="ct-pnd-field-ngayCt" value={form.ngayCt} onChange={event => patchForm({ ngayCt: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Ngày lập</label>
                <Input type="date" disabled={readOnly} data-testid="ct-pnd-field-ngayLct" value={form.ngayLct} onChange={event => patchForm({ ngayLct: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Số C.từ</label>
                <Input maxLength={30} disabled={readOnly} data-testid="ct-pnd-field-soCt" value={form.soCt} onChange={event => patchForm({ soCt: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Số lô</label>
                <Input maxLength={30} disabled={readOnly} data-testid="ct-pnd-field-soLo" value={form.soLo} onChange={event => patchForm({ soLo: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Ngày lô</label>
                <Input type="date" disabled={readOnly} data-testid="ct-pnd-field-ngayLo" value={form.ngayLo} onChange={event => patchForm({ ngayLo: event.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Đối tượng</h2>
            <div className={df.row4}>
              <div>
                <label className={df.label}>Đối tượng</label>
                <Input maxLength={30} disabled={readOnly} data-testid="ct-pnd-field-maKh" value={form.maKh} onChange={event => patchForm({ maKh: event.target.value })} onBlur={() => { void onBlurCustomer(); }} />
              </div>
              <div>
                <label className={df.label}>Tên đối tượng</label>
                <Input disabled data-testid="ct-pnd-field-tenKh" value={form.tenKh} />
              </div>
              <div>
                <label className={df.label}>Người giao</label>
                <Input maxLength={200} disabled={readOnly} data-testid="ct-pnd-field-ongBa" value={form.ongBa} onChange={event => patchForm({ ongBa: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Địa chỉ</label>
                <Input maxLength={200} disabled={readOnly} data-testid="ct-pnd-field-diaChi" value={form.diaChi} onChange={event => patchForm({ diaChi: event.target.value })} />
              </div>
              <div className={df.spanCol2}>
                <label className={df.label}>Diễn giải</label>
                <Input maxLength={200} disabled={readOnly} data-testid="ct-pnd-field-dienGiai" value={form.dienGiai} onChange={event => patchForm({ dienGiai: event.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tiền tệ và lệnh</h2>
            <div className={df.row4}>
              <div>
                <label className={df.label}>Ngoại tệ</label>
                <Input maxLength={3} disabled={readOnly} data-testid="ct-pnd-field-maNt" value={form.maNt} onChange={event => patchForm({ maNt: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Tỷ giá</label>
                <Input inputMode="decimal" disabled={readOnly} data-testid="ct-pnd-field-tyGia" value={form.tyGia} onChange={event => patchForm({ tyGia: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Lệnh số</label>
                <Input maxLength={30} disabled={readOnly} data-testid="ct-pnd-field-lenhSo" value={form.lenhSo} onChange={event => patchForm({ lenhSo: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Lệnh PO</label>
                <Input maxLength={30} disabled={readOnly} data-testid="ct-pnd-field-lenhPo" value={form.lenhPo} onChange={event => patchForm({ lenhPo: event.target.value })} />
              </div>
              <div>
                <label className={df.label}>Lệnh RO</label>
                <Input maxLength={30} disabled={readOnly} data-testid="ct-pnd-field-lenhRo" value={form.lenhRo} onChange={event => patchForm({ lenhRo: event.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Tổng</h2>
            <div className={df.row4}>
              <div>
                <label className={df.label}>Tổng số lượng</label>
                <Input disabled data-testid="ct-pnd-field-tSoLuong" value={showMoney(totals.tSoLuong)} />
              </div>
              <div>
                <label className={df.label}>Tổng số lượng 1</label>
                <Input disabled data-testid="ct-pnd-field-tSoLuong1" value={form.tSoLuong1} />
              </div>
              <div>
                <label className={df.label}>Tổng Ps NT</label>
                <Input disabled data-testid="ct-pnd-field-tTienNt" value={showMoney(totals.tTienNt)} />
              </div>
              <div>
                <label className={df.label}>Tổng Phát sinh</label>
                <Input disabled data-testid="ct-pnd-field-tTien" value={showMoney(totals.tTien)} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng</h2>
            {!readOnly && (
              <div>
                <Button className={df.btnAddLine} data-testid="ct-pnd-line-add-btn" onClick={() => {
                  setLines(prev => [...prev, emptyLine()]);
                  setSelectedLine(lines.length);
                  markDirty();
                }}>Thêm dòng</Button>
                <Button className={df.btnDeleteLine} data-testid="ct-pnd-line-remove-btn" disabled={selectedLine < 0} onClick={() => {
                  setLines(prev => prev.filter((_, i) => i !== selectedLine));
                  setSelectedLine(-1);
                  markDirty();
                }}>Xóa dòng</Button>
              </div>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable} data-testid="ct-pnd-line-grid">
                <thead>
                  <tr>
                    {lineColumns.slice(0, 11).map(col => <th key={col.key}>{col.header}</th>)}
                    <th>Giá VNĐ</th>
                    <th>Thành tiền</th>
                    {lineColumns.slice(11).map(col => <th key={col.key}>{col.header}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {lines.map((line, index) => (
                    <tr
                      key={`${line.sttRec0}-${index}`}
                      aria-selected={index === selectedLine}
                      style={index === selectedLine ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                      onClick={() => setSelectedLine(index)}
                    >
                      {lineColumns.slice(0, 11).map(col => renderLineInput(line, index, col))}
                      <td>
                        <Input disabled data-testid={`ct-pnd-line-${index}-gia`} value={showMoney(previewGia(line.giaNt, form.tyGia))} />
                      </td>
                      <td>
                        <Input disabled data-testid={`ct-pnd-line-${index}-tien`} value={showMoney(previewTien(line.tienNt, form.tyGia))} />
                      </td>
                      {lineColumns.slice(11).map(col => renderLineInput(line, index, col))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          <div className={df.footer}>
            <span className={df.totalLabel}>Tổng Phát sinh</span>
            <span className={df.totalValue}>{showMoney(totals.tTien)}</span>
          </div>
        </>
      )}
    </div>
  );
};

export default PndFormPage;
